<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {latestPackage} from '../api';import {db,queueAttempt,syncAttempts} from '../offline/db';
import type {AttemptEvent,ContentItem} from '../domain';
import {emojiFor,loadThemeProgress,saveThemeProgress,themeSeedItems,themeWorlds,type ThemeProgress} from '../game/worldCatalog';
const route=useRoute(),router=useRouter();const world=computed(()=>themeWorlds.find(x=>x.id===route.params.worldId));
const items=ref<ContentItem[]>([]),stageIndex=ref(0),round=ref(0),phase=ref<'loading'|'intro'|'playing'|'celebrating'|'complete'>('loading');
const progressState=ref<ThemeProgress>({unlockedStage:0,bestStars:{},completed:false});const discovered=ref<string[]>([]),options=ref<ContentItem[]>([]),selectedAudio=ref('');
const mistakes=ref(0),stars=ref(0),earned=ref(0),message=ref(''),soundEnabled=ref(true);let packageVersion='starter-1',sessionId=crypto.randomUUID(),started=0,timer:ReturnType<typeof setTimeout>|undefined;
const stage=computed(()=>world.value?.stages[stageIndex.value]);const current=computed(()=>items.value[round.value%Math.max(items.value.length,1)]);
const total=computed(()=>items.value.length);const progress=computed(()=>stage.value?.kind==='DISCOVER_CARDS'?discovered.value.length/Math.max(total.value,1)*100:(phase.value==='complete'?100:round.value/Math.max(total.value,1)*100));
const isChoose=computed(()=>stage.value?.kind==='LISTEN_IMAGE'||stage.value?.kind==='COMMAND_IMAGE'||(stage.value?.kind==='MIXED_CHALLENGE'&&round.value%2===0));const isAudio=computed(()=>stage.value?.kind==='AUDIO_MATCH'||(stage.value?.kind==='MIXED_CHALLENGE'&&round.value%2===1));
function speak(text:string){if(!soundEnabled.value||!text||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.82;u.pitch=1.06;window.speechSynthesis.speak(u)}
function taskText(){return stage.value?.kind==='COMMAND_IMAGE'||(stage.value?.kind==='MIXED_CHALLENGE'&&round.value%3===0)?'Find the '+current.value.text+'.':current.value.text}
function speakTask(){speak(taskText())}
function shuffle<T>(a:T[]){return [...a].sort((x,y)=>((String((x as any).id).charCodeAt(0)+round.value*7)%11)-((String((y as any).id).charCodeAt(0)+round.value*7)%11))}
function prep(){const rest=items.value.filter(x=>x.id!==current.value.id);options.value=shuffle([current.value,...shuffle(rest).slice(0,2)]);selectedAudio.value=''}
function begin(){round.value=0;stars.value=0;mistakes.value=0;discovered.value=[];sessionId=crypto.randomUUID();phase.value='playing';if(stage.value?.kind!=='DISCOVER_CARDS'){prep();started=performance.now();setTimeout(speakTask,250)}message.value=stage.value?.kind==='DISCOVER_CARDS'?'点一点卡片，听听每个物品的英文。':stage.value?.subtitle||''}
function openStage(i:number){if(i>progressState.value.unlockedStage)return;stageIndex.value=i;round.value=0;stars.value=0;phase.value='intro';message.value=stage.value?.goal||''}
function visual(item:ContentItem){return world.value?emojiFor(world.value,item.text):'✨'}
async function explore(item:ContentItem){if(stage.value?.kind!=='DISCOVER_CARDS'||phase.value!=='playing')return;speak(item.text);if(!discovered.value.includes(item.id))discovered.value=[...discovered.value,item.id];message.value=item.text+' · '+item.meaningCn;if(discovered.value.length>=items.value.length)setTimeout(finish,600)}
function wrong(){mistakes.value++;message.value=mistakes.value>1?'没关系，再认真听一次。':'差一点，再试试～';speakTask()}
function score(){return mistakes.value===0?3:mistakes.value===1?2:1}
async function record(type:string){const e:AttemptEvent={eventId:crypto.randomUUID(),sessionId,contentItemId:current.value.id,packageVersion,activityVersion:(stageIndex.value+1),firstTryCorrect:mistakes.value===0,semanticErrors:mistakes.value,hintLevel:0,responseMs:Math.round(performance.now()-started),occurredAt:new Date().toISOString(),syncStatus:'PENDING',worldId:world.value?.id,stageId:stage.value?.id,activityType:type};try{await queueAttempt(e)}catch{}}
async function correct(type:string){phase.value='celebrating';earned.value=score();stars.value+=earned.value;await record(type);timer=setTimeout(()=>{if(round.value+1>=total.value)finish();else{round.value++;mistakes.value=0;phase.value='playing';prep();started=performance.now();setTimeout(speakTask,250)}},900)}
async function choose(item:ContentItem){if(!isChoose.value||phase.value!=='playing')return;if(item.id!==current.value.id){wrong();return}await correct(stage.value?.kind==='COMMAND_IMAGE'?'COMMAND_IMAGE':'LISTEN_IMAGE')}
function playChoice(item:ContentItem){selectedAudio.value=item.id;speak(item.text)}
async function confirmAudio(){if(!selectedAudio.value){message.value='先试听一个声音。';return}if(selectedAudio.value!==current.value.id){selectedAudio.value='';wrong();return}await correct('AUDIO_MATCH')}
function finish(){phase.value='complete';const key=stage.value!.id;if(stage.value?.kind!=='DISCOVER_CARDS')progressState.value.bestStars[key]=Math.max(progressState.value.bestStars[key]??0,stars.value);if(stageIndex.value<4)progressState.value.unlockedStage=Math.max(progressState.value.unlockedStage,stageIndex.value+1);else progressState.value.completed=true;saveThemeProgress(world.value!.id,progressState.value);message.value=stageIndex.value===4?world.value!.title+'全部完成！':'这个阶段完成啦，继续下一步吧！';syncNow()}
function next(){if(stageIndex.value<4)openStage(stageIndex.value+1);else{const i=themeWorlds.findIndex(x=>x.id===world.value?.id);const n=themeWorlds[i+1];router.push(n?'/kid/world/'+n.id:'/kid')}}
function syncNow(){syncAttempts(localStorage.getItem('kidToken')??'').catch(()=>{})}
async function load(){const w=world.value;if(!w){router.replace('/kid');return}progressState.value=loadThemeProgress(w.id);let published:ContentItem[]=[];try{const pkg=await latestPackage();packageVersion=pkg.packageVersion;published=pkg.items;await db.packages.put(pkg)}catch{try{const pkg=await db.packages.orderBy('publishedAt').last();if(pkg){packageVersion=pkg.packageVersion;published=pkg.items}}catch{}}items.value=themeSeedItems(w,published);phase.value='intro';message.value=w.stages[0].goal}
watch(()=>route.params.worldId,()=>void load());onMounted(()=>void load());onBeforeUnmount(()=>{if(timer)clearTimeout(timer);window.speechSynthesis?.cancel()});
</script>
<template><main v-if="world&&stage" class="theme" :class="'world-'+world.order"><div class="page">
<header><button class="back" @click="router.push('/kid')">← 世界地图</button><div><small>{{world.code}} · {{world.englishTitle}}</small><h1>{{world.icon}} {{world.title}}</h1></div><button class="sound" @click="soundEnabled=!soundEnabled">{{soundEnabled?'🔊':'🔇'}}</button></header>
<nav class="stage-map"><button v-for="(s,i) in world.stages" :key="s.id" :disabled="i>progressState.unlockedStage" :class="{active:i===stageIndex,locked:i>progressState.unlockedStage,done:i<progressState.unlockedStage||progressState.completed}" @click="openStage(i)"><span>{{i>progressState.unlockedStage?'🔒':['🔎','🃏','🎧','👉','🏆'][i]}}</span><b>{{s.code}}</b><small>{{s.title}}</small><em v-if="progressState.bestStars[s.id]">⭐{{progressState.bestStars[s.id]}}</em></button></nav>
<section class="bar"><div><strong>{{stage.code}} · {{stage.title}}</strong><span>{{stage.goal}}</span></div><b v-if="stage.kind!=='DISCOVER_CARDS'">⭐ {{stars}} · {{Math.min(round+1,total)}}/{{total}}</b><b v-else>发现 {{discovered.length}}/{{total}}</b><div class="line"><i :style="{width:progress+'%'}"></i></div></section>
<section class="board">
 <div class="scene-decor"><span>{{world.icon}}</span><h2>{{world.englishTitle}}</h2><p>{{world.description}}</p></div>
 <div v-if="phase==='playing'" class="activity">
  <template v-if="stage.kind==='DISCOVER_CARDS'"><div class="cards discover"><button v-for="item in items" :key="item.id" :class="{seen:discovered.includes(item.id)}" @click="explore(item)"><span>{{visual(item)}}</span><b>{{discovered.includes(item.id)?item.text:'?'}}</b></button></div></template>
  <template v-else-if="isChoose"><div class="prompt"><button @click="speakTask">🔊 再听一次</button><p>{{stage.kind==='COMMAND_IMAGE'?'听指令，找到正确物品':'听单词，找到正确图片'}}</p></div><div class="cards choices"><button v-for="item in options" :key="item.id" @click="choose(item)"><span>{{visual(item)}}</span></button></div></template>
  <template v-else-if="isAudio"><div class="target"><span>{{visual(current)}}</span><b>这是什么？</b></div><div class="audio-choices"><button v-for="(item,i) in options" :key="item.id" :class="{chosen:selectedAudio===item.id}" @click="playChoice(item)">🔊 声音 {{String.fromCharCode(65+i)}}</button></div><button class="confirm" @click="confirmAudio">确认答案 ✓</button></template>
 </div>
 <div v-if="phase==='intro'" class="overlay"><div class="modal"><span class="big">{{world.icon}}</span><small>{{stage.code}}</small><h2>{{stage.title}}</h2><p>{{stage.subtitle}}</p><p class="goal">{{stage.goal}}</p><button @click="begin">开始这一阶段 🚀</button></div></div>
 <div v-if="phase==='complete'" class="overlay"><div class="modal"><span class="big">🎉</span><h2>{{stageIndex===4?'世界完成！':'阶段完成！'}}</h2><p>{{message}}</p><div v-if="stage.kind!=='DISCOVER_CARDS'" class="stars">⭐ {{stars}} / {{total*3}}</div><div class="actions"><button class="plain" @click="begin">再练一次</button><button @click="next">{{stageIndex===4?'进入下一个世界':'下一阶段 →'}}</button></div></div></div>
 <div v-if="phase==='celebrating'" class="pop">⭐ +{{earned}}</div>
</section>
<section class="coach"><span>🐰</span><div><small>向导乐乐</small><h3>{{phase==='playing'&&stage.kind!=='DISCOVER_CARDS'?taskText():stage.title}}</h3><p>{{message}}</p></div></section>
</div></main></template>
<style scoped>
.theme{min-height:100vh;background:radial-gradient(circle at 15% 5%,#fff0cf,transparent 28%),radial-gradient(circle at 88% 8%,#d9f4ef,transparent 28%),#f3f7ff;font-family:system-ui,"Microsoft YaHei",sans-serif;color:#3c4c64}.page{max-width:1080px;margin:auto;padding:18px 22px 45px}header{display:flex;align-items:center;justify-content:space-between;gap:15px;background:#fff;padding:15px 20px;border-radius:22px;box-shadow:0 7px 0 #e0e5f3}header>div{text-align:center}header small{font-weight:900;color:#9684ce;letter-spacing:1.2px}header h1{margin:2px;font-size:24px;color:#5c4da4}.back,.sound{border:0;border-radius:13px;background:#eeeafd;color:#6553af;padding:11px 14px;font-weight:850}.sound{font-size:20px}.stage-map{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:16px 0}.stage-map button{position:relative;border:3px solid #fff;background:#fff;border-radius:18px;padding:9px;color:#747b92;box-shadow:0 5px 0 #dfe5f1}.stage-map span{display:block;font-size:21px}.stage-map b,.stage-map small{display:block}.stage-map b{color:#7461bd}.stage-map small{font-size:10px}.stage-map em{position:absolute;top:4px;right:5px;font-size:9px;font-style:normal}.stage-map .active{background:#f0edff;border-color:#b7a8ed}.stage-map .locked{opacity:.5}.stage-map .done{box-shadow:0 5px 0 #c2e6d1}.bar{position:relative;background:#fff;padding:14px 18px 20px;border-radius:20px;margin-bottom:13px;display:flex;justify-content:space-between;gap:14px;align-items:center}.bar>div:first-child{display:flex;flex-direction:column}.bar span{font-size:11px;color:#8b93a3}.line{position:absolute;left:18px;right:18px;bottom:8px;height:7px;background:#e8eaf3;border-radius:9px;overflow:hidden}.line i{display:block;height:100%;background:linear-gradient(90deg,#73d3af,#f0c658)}.board{position:relative;min-height:470px;overflow:hidden;border:8px solid #fff;border-radius:30px;background:linear-gradient(180deg,#d9f0ea,#f8e9c9);box-shadow:0 11px 0 #d5ddec}.scene-decor{text-align:center;padding:20px}.scene-decor>span{font-size:60px}.scene-decor h2{margin:0;color:#6554a6}.scene-decor p{margin:5px;color:#7e8796}.activity{padding:0 24px 28px}.cards{display:grid;gap:12px}.cards.discover{grid-template-columns:repeat(4,1fr)}.cards.choices{grid-template-columns:repeat(3,1fr);max-width:700px;margin:auto}.cards button{border:4px solid #fff;background:#fffdf8;border-radius:24px;padding:15px;box-shadow:0 6px 0 #d8d5e8;cursor:pointer}.cards button>span{font-size:58px;display:block}.cards button b{display:block;color:#6552aa;font-size:16px}.cards button.seen{background:#effaf2;box-shadow:0 6px 0 #bfe0c8}.prompt{text-align:center;margin-bottom:14px}.prompt button,.confirm{border:0;border-radius:15px;background:#816bd0;color:white;padding:12px 17px;font-weight:900}.prompt p{margin:7px;color:#676f82}.target{text-align:center}.target span{font-size:88px;display:block}.target b{color:#6958ad}.audio-choices{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin:16px}.audio-choices button{border:3px solid #fff;background:#fff;border-radius:16px;padding:14px 18px;color:#655b91;font-weight:850}.audio-choices .chosen{background:#eee9ff;border-color:#9c87df}.confirm{display:block;margin:auto;background:#70b98f}.overlay{position:absolute;inset:0;background:#3b3b625e;display:grid;place-items:center;padding:20px;z-index:3}.modal{width:min(440px,94%);box-sizing:border-box;text-align:center;background:#fffdf8;border:5px solid #fff1c8;border-radius:28px;padding:26px;box-shadow:0 11px 0 #ce9fc6}.modal .big{font-size:55px}.modal small{display:block;color:#9788cd;font-weight:900}.modal h2{color:#6250a6;font-size:27px;margin:5px}.modal p{color:#70798b}.modal .goal{font-size:12px;background:#f1eff9;padding:9px;border-radius:12px}.modal button{border:0;background:#ffc463;color:#68421e;font-size:16px;font-weight:900;border-radius:17px;padding:13px 22px}.actions{display:flex;justify-content:center;gap:10px}.actions .plain{background:#eae7f8;color:#6558a2}.stars{font-size:30px;font-weight:900;color:#d69335;margin:11px}.pop{position:absolute;z-index:5;left:50%;top:42%;transform:translate(-50%,-50%);font-size:42px;font-weight:950;background:#fff3bd;color:#d98a27;padding:15px 28px;border-radius:24px;box-shadow:0 7px 0 #f1c354}.coach{display:flex;gap:13px;align-items:center;background:#fff;margin-top:20px;padding:14px 18px;border-radius:22px;box-shadow:0 6px 0 #e1e5f0}.coach>span{font-size:44px}.coach small{font-weight:800;color:#a48248}.coach h3{margin:1px 0;color:#6551aa}.coach p{margin:2px;color:#81899a;font-size:12px}@media(max-width:650px){.page{padding:9px}.stage-map{overflow-x:auto;grid-template-columns:repeat(5,minmax(78px,1fr))}.cards.discover{grid-template-columns:repeat(2,1fr)}.cards button>span{font-size:45px}.board{min-height:430px}.scene-decor p{display:none}.back{font-size:0}.back::after{content:'←';font-size:18px}}</style>
